/**  Pas encore décidée (Q-30). */
"non_statue" | 
/**  Passe au niveau supérieur. */
"admis" | 
/**  Redouble. */
"redouble" | 
/**  Exclu. */
"exclu" | 
/**  Passe un rattrapage. */
"rattrapage";

