	/**  Reçus valides. */
	nombre: number,
	/**  Total encaissé, annulations déduites. */
	total: Montant,
	/**  Versements annulés. */
	annules: number,
	/**  Montant des versements annulés. */
	montant_annule: Montant,
	/**  Caissiers de la période, tous filtres de caissier et de mode ignorés. */
