"avant_facturation";

/**
 *  Mouvement de caisse hors encaissement (SPEC_PHASE_3 §8, blueprint §8.8) : la sortie de
 *  régularisation d'un versement annulé après la clôture de sa session ; depuis la phase 7, les
 *  salaires et les avances payés en espèces, et l'entrée qui remet un paiement annulé.
 */
export type MouvementCaisse = {
	/**  Identifiant technique. */
	id: string,
	/**  Établissement. */
	etablissement_id: string,
	/**  Session où la sortie est passée : celle, ouverte, de qui annule. */
	session_id: string,
	/**  Montant sorti. */
	montant: Montant,
	/**  Mode : seules les espèces sortent du tiroir. */
	mode: ModePaiement,
	/**  Motif. */
	motif: string,
	/**  Versement annulé que la sortie régularise. */
	versement_id: string | null,
	/**  Instant. */
	le: number,
	/**  Auteur. */
	par: string,
	/**  Nature. */
	nature: NatureMouvement,
	/**  Paiement du personnel que le mouvement porte, ou dont il remet l'annulation. */
	paiement_id: string | null,
	/**  Dépense que le mouvement porte, ou dont il remet l'annulation. */
	depense_id: string | null,
	/**  Transfert que le mouvement porte. */
	transfert_id: string | null,
	/**  Recette que le mouvement porte, ou dont il sort l'annulation. */
	recette_id: string | null,
};

/**  Comment le membre est payé ; la paie de la phase 7 s'en sert. */
export type MoyenPaiement = 
/**  En espèces, à la caisse. */
{ mode: "especes" } | 
/**  Par mobile money, sur ce numéro (forme canonique). */
{ mode: "mobile_money"; 
/**  Numéro. */
numero: string } | 
/**  Par virement, sur ce compte. */
{ mode: "banque"; 
/**  Banque. */
banque: string; 
/**  Numéro de compte, tel qu'écrit par la banque. */
compte: string };

/**
 *  Moyenne d'une période reprise du relevé officiel d'une autre école, pour un élève arrivé
 *  après elle (Q-28) : jamais les notes de détail, seulement la moyenne, avec sa source.
 */
export type MoyenneReprise = {
	/**  Inscription de l'élève. */
	inscription_id: string,
	/**  Période qu'il a suivie ailleurs. */
	periode_id: string,
	/**  Moyenne générale de la période, en centièmes du barème du niveau. */
	moyenne: number,
	/**  École qui a délivré le relevé. */
	etablissement_origine: string,
	/**  Référence du relevé présenté. */
	piece: string,
};

/**  Absence ou retard. */
export type NatureAbsence = 
/**  Absent toute la demi-journée. */
"absence" | 
/**  Arrivé en retard. */
"retard";

/**  Nature d'une absence du personnel. */
export type NatureAbsencePersonnel = 
/**  Absent toute la journée. */
"journee" | 
/**  Absent une demi-journée. */
"demi_journee" | 
/**  Arrivé en retard. */
"retard";

/**  Nature de la pièce d'état civil d'un élève. */
export type NatureActe = 
/**  Acte de naissance. */
"acte" | 
/**  Jugement supplétif. */
"jugement_suppletif";

/**  Nature d'un compte de trésorerie. */
export type NatureCompte = 
/**  La caisse de l'école, faite de ses sessions : une seule. */
"caisse" | 
/**  Un compte en banque. */
"banque" | 
/**  Un compte mobile money (Orange Money, Moov Money, Wave). */
"mobile_money";

/**  Ce qu'un conflit signale. */
export type NatureConflit = 
/**  L'enseignant a une autre séance en même temps. */
"enseignant" | 
/**  La salle est prise par une autre séance en même temps. */
"salle" | 
/**  La séance empiète sur une récréation. */
"recreation" | 
/**  La matière a plus d'heures que le programme ne prévoit. */
"volume";

/**  Nature d'un élément de paie. */
export type NatureElement = 
/**  S'ajoute au brut : salaire, prime, indemnité, heures, rappel. */
"gain" | 
/**  Se retire du brut, à la charge du membre : cotisation salariale, impôt, retenue. */
"retenue" | 
/**  À la charge de l'école, calculée pour les déclarations ; ne touche jamais le net. */
"cotisation_patronale";

/**  Nature d'un engagement. */
export type NatureEngagement = 
/**  À durée indéterminée : salaire mensuel, sans fin. */
"duree_indeterminee" | 
/**  À durée déterminée : salaire mensuel, fin exigée. */
"duree_determinee" | 
/**  Vacation : taux de l'heure et heures prévues par semaine, pour l'année. */
"vacation" | 
/**  Stage : indemnité mensuelle, éventuellement nulle ; fin exigée. */
"stage" | 
/**  Bénévole : sans rémunération. */
"benevole";

/**  Exclusion temporaire ou définitive. */
export type NatureExclusion = 
/**  Quelques jours, avec une date de retour : l'élève reste inscrit. */
"temporaire" | 
/**  L'élève quitte l'école ; la direction peut revenir sur la décision et le réintégrer. */
"definitive";

/**  Ce qu'une ligne crée. */
export type NatureLigneReferentiel = 
/**  Une classe de l'année en cours. */
"classe" | 
/**  Une matière. */
"matiere";

/**  Nature d'un message : ce dont il parle. */
export type NatureMessage = 
/**  Bulletin à retirer. */
"bulletin" | 
/**  Relance d'impayé. */
"impaye" | 
/**  Absence du jour. */
"absence" | 
/**  Convocation, préparée puis décidée. */
"convocation" | 
/**  Avis de sanction, préparé puis décidé. */
"sanction" | 
/**  Message d'essai de la clé, vers un numéro saisi. */
"essai" | 
/**  Réponse à une consultation par SMS entrant (SPEC_PHASE_5 §9). */
"consultation";

/**  Nature d'un mouvement de caisse hors encaissement. */
export type NatureMouvement = 
/**  Sortie qui régularise un versement annulé après la clôture de sa session (phase 3). */
"sortie_regularisation" | 
/**  Salaire payé en espèces de la caisse (SPEC_PHASE_7 §7). */
"sortie_salaire" | 
/**  Avance versée en espèces de la caisse. */
"sortie_avance" | 
/**  Dépense payée en espèces de la caisse (SPEC_PHASE_8 §3). */
"sortie_depense" | 
/**  Espèces déposées sur un autre compte de l'école (SPEC_PHASE_8 §5). */
"sortie_transfert" | 
/**  Entrée qui remet dans la caisse un paiement du personnel annulé. */
"entree_regularisation" | 
/**  Espèces retirées d'un autre compte de l'école. */
"entree_transfert" | 
/**  Recette hors des versements des parents : un don, une location (SPEC_VERSION_1_1). */
"entree_recette";

/**  Nature d'une pièce du dossier. */
export type NaturePiece = 
/**  Pièce d'identité. */
"identite" | 
/**  Diplôme. */
"diplome" | 
/**  Engagement signé. */
"engagement" | 
/**  Autre pièce. */
"autre";

/**  Nature d'une sanction. */
export type NatureSanction = 
/**  Avertissement, de la direction ou du conseil de classe. */
"avertissement" | 
/**  Blâme, de la direction ou du conseil de classe. */
"blame" | 
/**  Retenue : heures de travail en dehors des cours. */
"retenue" | 
/**  Convocation des parents. */
"convocation_parents";

/**  Niveau d'un établissement, copie du référentiel national que l'école renomme ou désactive. */
export type Niveau = {
	/**  Identifiant technique. */
	id: string,
	/**  Établissement propriétaire. */
	etablissement_id: string,
	/**  Code national, stable : `PS`, `1`, `12`. */
	code: string,
	/**  Libellé affiché, modifiable. */
	libelle: string,
	/**  Cycle. */
	cycle: Cycle,
	/**  Ordre d'affichage, de 1 (petite section) à 15 (12e année). */
	ordre: number,
	/**  Mode d'évaluation. */
	mode_evaluation: ModeEvaluation,
	/**  Diplôme terminal. */
	diplome_terminal: DiplomeTerminal,
	/**  Faux pour un niveau que l'école n'enseigne pas. */
	actif: boolean,
};

/**  Note d'un élève à une évaluation. */
export type NoteEleve = {
	/**  Évaluation. */
	evaluation_id: string,
	/**  Inscription de l'élève. */
	inscription_id: string,
	/**  Note en centièmes ; absente pour un absent ou un dispensé. */
	valeur: number | null,
	/**  Absent. */
	absent: boolean,
	/**  Absence justifiée. */
	justifie: boolean,
	/**  Dispensé. */
	dispense: boolean,
};

/**  Ce qui est payé. */
export type ObjetPaiement = 
/**  Le net d'un bulletin de paie validé. */
"salaire" | 
/**  Une avance accordée. */
"avance";

/**  Nature de la mutation auditée. */
export type Operation = 
/**  Création d'une entité. */
"creation" | 
/**  Modification de champs. */
"modification" | 
/**  Suppression logique. */
"suppression" | 
/**  Changement d'état d'une machine à états. */
"transition" | 
/**  Annulation par écriture inverse (ADR-010). */
"annulation" | 
/**  Connexion, déverrouillage, bascule d'utilisateur. */
"session" | 
/**  Accès à une fonction sensible : sauvegarde, restauration, export. */
"acces";

/**  D'où vient une ligne du livre. */
export type OrigineLigne = 
/**  Un versement d'un parent. */
"versement" | 
/**  Un mouvement de la caisse : salaire, avance, dépense, régularisation, transfert. */
"mouvement" | 
/**  Une dépense payée d'une banque ou d'un compte mobile money, salaires et avances compris. */
"depense" | 
/**  Un transfert, côté banque ou mobile money. */
"transfert" | 
/**  Une autre recette sur une banque ou un compte mobile money. */
"recette";

