/**  Totaux d'une session. */
export type TotauxSession = {
	/**  Fonds initial. */
	fonds: Montant,
	/**  Encaissements en espèces. */
	entrees_especes: Montant,
	/**  Sorties d'espèces (régularisations). */
	sorties_especes: Montant,
	/**  Espèces attendues dans le tiroir. */
	theorique: Montant,
	/**  Encaissements par mode, espèces comprises ; hors du tiroir pour les autres modes. */
	par_mode: TotalMode[],
	/**  Reçus émis pendant la session et comptés dans ses totaux. */
	nombre_recus: number,
	/**  Sorties de régularisation passées dans la session, tous modes. */
	regularisations: MouvementCaisse[],
};

/**  Traitement d'un absent non justifié (T-29, RC-3). */
export type TraitementAbsence = 
/**  Exclu du calcul, numérateur et dénominateur. Défaut. */
"exclu" | 
/**  Compté zéro. */
"zero";

/**  Tranche d'un plan de paiement. */
export type Tranche = {
	/**  Libellé : « 1re tranche », « Octobre ». */
	libelle: string,
	/**  Date d'échéance. */
	echeance: string,
	/**  Part du montant, en pourcentage entier. */
	part: number,
};

/**
 *  Tranche d'ancienneté d'un impayé, comptée depuis la plus ancienne échéance passée et non
 *  soldée (T-20).
 */
export type TrancheAnciennete = 
/**  De 0 à 30 jours. */
"de_0_a_30" | 
/**  De 31 à 60 jours. */
"de_31_a_60" | 
/**  De 61 à 90 jours. */
"de_61_a_90" | 
/**  Plus de 90 jours. */
"plus_de_90";

/**  TrancheBareme d'un barème progressif. */
export type TrancheBareme = {
	/**  Borne haute, comprise ; absente pour la dernière tranche. */
	jusqua: Montant | null,
	/**  Taux de la tranche, en centièmes de pour cent. */
	taux: number,
};

/**  Transfert enregistré. */
export type TransfertEnregistre = {
	/**  Inscription transférée. */
	inscription: Inscription,
	/**  Numéro du certificat de transfert. */
	numero_certificat: string,
	/**  Reste dû sur les échéances échues au jour du départ. */
	reste_du: Montant,
	/**  Échéances à venir annulées. */
	echeances_annulees: number,
	/**  Clés des avertissements, qui n'empêchent rien. */
	avertissements: string[],
};

/**  Catégories, comptes et réglages. */
export type Tresorerie = {
	/**  Catégories, recettes puis dépenses. */
	categories: CategorieTresorerie[],
	/**  Comptes, la caisse d'abord. */
	comptes: CompteTresorerie[],
	/**  Réglages. */
	reglages: ReglagesTresorerie,
};

/**  Type d'évaluation permis dans le cycle, avec son barème usuel en centièmes. */
export type TypeAutorise = {
	/**  Type. */
	type_evaluation: TypeEvaluation,
	/**  Barème proposé à la création d'une évaluation, en centièmes (`2000` pour 20). */
	bareme: number,
};

/**  Type de congé, propre à l'école. */
export type TypeConge = {
	/**  Identifiant technique. */
	id: string,
	/**  Établissement. */
	etablissement_id: string,
	/**  Code stable d'un type livré ; absent pour un type ajouté par l'école. */
	code: string | null,
	/**  Libellé. */
	libelle: string,
	/**  Rang dans la liste. */
	ordre: number,
	/**  Proposé aux demandes ; un type retiré reste sur les congés qui le portent. */
	actif: boolean,
	/**  Ses jours se déduisent du solde, quand le décompte est actif : le congé annuel. */
	deduit_du_solde: boolean,
};

/**  Type d'évaluation. */
export type TypeEvaluation = 
/**  Devoir, interrogation : la moyenne des devoirs fait la note de classe (T-28). */
"devoir" | 
/**  Composition de fin de période (mensuelle au 1er cycle). */
"composition";

/**  Nature d'un frais (blueprint §8.8, T-11). */
export type TypeFrais = 
/**  Frais d'inscription, dus à l'inscription. */
"inscription" | 
/**  Scolarité, payée selon le plan choisi par le parent. */
"scolarite" | 
/**  Cantine. */
"cantine" | 
/**  Transport. */
"transport" | 
/**  Tenue. */
"tenue" | 
/**  Frais d'examen. */
"examen" | 
/**  Autre frais. */
"autre";

/**  Nature d'une inscription, déduite et non saisie (SPEC_PHASE_2 §5.1). */
export type TypeInscription = 
/**  Premier passage dans l'école. */
"nouvelle" | 
/**  L'élève a une inscription validée d'une année antérieure. */
"reinscription" | 
/**  L'élève vient d'une autre école, qui est indiquée. */
"transfert_entrant";

/**
 *  Type de message aux familles, objet du consentement (§25.6) : un parent qui ne veut plus de
 *  relances garde l'avis de bulletin.
 */
export type TypeMessage = 
/**  Bulletin à retirer. */
"bulletin" | 
/**  Relance d'impayé. */
"impaye" | 
/**  Absence du jour. */
"absence" | 
/**  Convocation. */
"convocation";

/**  Nature d'une période. */
export type TypePeriode = 
/**  Un mois, une composition (1er cycle). */
"mensuelle" | 
/**  Un trimestre. */
"trimestre" | 
/**  Un semestre, dans l'enseignement technique seulement. */
"semestre";

/**  Nature d'une remise (blueprint §8.8, T-17). */
export type TypeRemise = 
/**  Bourse. */
"bourse" | 
/**  Demi-bourse. */
"demi_bourse" | 
/**  Réduction accordée à une fratrie. */
"fratrie" | 
/**  Enfant d'un membre du personnel. */
"enfant_personnel" | 
/**  Arrangement avec la famille. */
"arrangement";

/**
 *  Compte d'un utilisateur de l'établissement. Les secrets (empreintes du mot de passe et du PIN)
 *  ne font pas partie de l'entité : ils vivent dans la couche d'authentification et n'apparaissent
 *  jamais dans une sérialisation (R-25).
 */
export type Utilisateur = {
	/**  Identifiant technique. */
	id: string,
	/**  Établissement de rattachement. */
	etablissement_id: string,
	/**  Identifiant de connexion, unique par établissement. */
	identifiant: string,
	/**  Nom affiché en permanence dans le bandeau (RA-13). */
	nom_affiche: string,
	/**  Compte actif. */
	actif: boolean,
	/**  Changement de mot de passe exigé à la prochaine connexion. */
	doit_changer_mot_de_passe: boolean,
	/**  Dernière connexion réussie. */
	derniere_connexion: number | null,
	/**  Échecs consécutifs d'authentification. */
	echecs_consecutifs: number,
	/**  Compte verrouillé jusqu'à cet instant après échecs répétés. */
	verrouille_jusqua: number | null,
};

/**  Valeur typée d'un paramètre. */
export type ValeurParametre = 
/**  Texte libre. */
{ type: "texte"; valeur: string } | 
/**  Entier signé. */
{ type: "entier"; valeur: number } | 
/**  Vrai ou faux. */
{ type: "booleen"; valeur: boolean };

/**  Valeur d'une remise : un pourcentage entier du frais visé, ou un montant. */
export type ValeurRemise = 
/**  Pourcentage entier, de 1 à 100. */
{ type: "taux"; 
/**  Pourcentage. */
pour_cent: number } | 
/**  Montant en francs, strictement positif. */
{ type: "montant"; 
/**  Montant. */
montant: Montant };

/**  Ce que dit la vérification d'un fichier d'archive. */
export type VerificationArchive = {
	/**  La signature est celle de cette école et le fichier n'a pas changé. */
	valide: boolean,
	/**  École. */
	etablissement: string,
	/**  Année. */
	annee: string,
	/**  Premier instant couvert. */
	du: number,
	/**  Dernier instant couvert. */
	au: number,
	/**  Lignes du journal. */
	lignes: number,
};

/**  Résultat d'une vérification complète de la chaîne d'audit. */
export type VerificationAudit = {
	/**  Lignes vérifiées. */
	lignes_verifiees: number,
};

/**  Versement d'un parent pour une inscription. */
export type Versement = {
	/**  Identifiant technique. */
	id: string,
	/**  Établissement. */
	etablissement_id: string,
	/**  Inscription. */
	inscription_id: string,
	/**  Facture réglée. */
	facture_id: string,
	/**  Session de caisse où il est encaissé. */
	session_id: string,
	/**  Numéro du reçu, sans trou : `REC-2026-000001` (R-46). */
	numero_recu: string,
	/**  Instant de l'encaissement. */
	encaisse_le: number,
	/**  Montant. */
	montant: Montant,
	/**  Mode de paiement. */
	mode: ModePaiement,
	/**  Référence de la transaction : exigée hors espèces (T-19). */
	reference: string,
	/**  Responsable payeur, s'il est enregistré. */
	payeur_id: string | null,
	/**  Nom du payeur imprimé sur le reçu : le responsable, ou un tiers (§3.6). */
	payeur_nom: string,
	/**  Caissier. */
	encaisse_par: string,
	/**  Clé tirée par l'écran : rejouer la même clé ne double pas la recette (R-35). */
	cle_idempotence: string,
	/**  État. */
	statut: StatutVersement,
	/**  Motif d'annulation. */
	motif_annulation: string,
};

/**  Version antérieure d'un bulletin, consultable. */
export type VersionBulletin = {
	/**  Bulletin. */
	id: string,
	/**  Version. */
	version: number,
	/**  État. */
	statut: StatutBulletin,
	/**  Publication. */
	publie_le: number | null,
};

/**  Version datée du calcul d'un élément : une paie applique celle en vigueur dans son mois. */
export type VersionElement = {
	/**  Identifiant technique. */
	id: string,
	/**  Établissement. */
	etablissement_id: string,
	/**  Élément. */
	element_id: string,
	/**  Premier mois d'application. */
	effet: string,
	/**  Calcul. */
	calcul: Calcul,
	/**  Retenues salariales retranchées du brut pour former l'assiette d'un taux ou d'un barème. */
	assiette_deduit: string[],
};
